KILO_STATIC_ASSERT(offsetof(kilo_telemetry_t, rate_pitch) == 6, kilo_sa_telemetry_rate_pitch);
KILO_STATIC_ASSERT(offsetof(kilo_telemetry_t, rate_roll) == 8, kilo_sa_telemetry_rate_roll);
