/* A host payload's length against its type: KILO_LEN_OK, KILO_LEN_BAD or KILO_LEN_UNKNOWN_TYPE. */
static inline uint8_t kilo_host_payload_len_check(uint8_t type, uint16_t len)
{
    switch (type) {
    case KILO_HOST_MSG_STATUS_REQ:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_CONTROL:
        return len == 2u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_KEEPALIVE:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_POSTURE:
        return len == 3u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_PARAM_GET:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_PARAM_SET:
        return len == 4u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REBOOT:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_TELEM_SUB:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_LOG_SUB:
        return len == 3u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_BRIDGE_OPEN:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_BRIDGE_TX:
        return (len >= 1u && len <= 200u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_BRIDGE_CLOSE:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_FLASH_BEGIN:
        return len == 13u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_FLASH_DATA:
        return (len >= 5u && len <= 204u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_FLASH_COMMIT:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_UPDATE_BEGIN:
        return len == 9u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_UPDATE_DATA:
        return (len >= 5u && len <= 204u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_UPDATE_COMMIT:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_WALK_LIST:
        return len == 4u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_WALK_FETCH:
        return len == 8u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_STATUS_REQ:
        return len == 0u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_FETCH:
        return len == 13u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_METRICS_REQ:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_BENCH:
        return len == 2u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_SAVE:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_DELETE:
        return len == 4u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_GUARD:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_CAL:
        return len == 4u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_RESULT:
        return (len >= 2u && len <= 62u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_STATUS:
        return len == 164u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_TELEM:
        return len == 136u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_LOG_LINE:
        return (len >= 9u && len <= 168u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_BRIDGE_RX:
        return (len >= 1u && len <= 200u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_WALK_INFO:
        return (len >= 48u && len <= 168u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_WALK_DATA:
        return (len >= 13u && len <= 213u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_REC_STATUS:
        return len == 86u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_METRICS:
        return (len >= 2u && len <= 202u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_BENCH_RESULT:
        return len == 31u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_GUARD_STATUS:
        return len == 31u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_SOUND:
        return (len >= 2u && len <= 17u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_SOUND_LIST:
        return len == 1u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_CAL_STATUS:
        return len == 34u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_SOUND_STATUS:
        return (len >= 29u && len <= 44u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_SOUND_INFO:
        return (len >= 8u && len <= 23u) ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_FLASH_STATUS:
        return len == 21u ? KILO_LEN_OK : KILO_LEN_BAD;
    case KILO_HOST_MSG_UPDATE_STATUS:
        return len == 22u ? KILO_LEN_OK : KILO_LEN_BAD;
    default:
        return KILO_LEN_UNKNOWN_TYPE;
    }
}

/* Kind of a host type (KILO_KIND_COMMAND, _STREAM, _EVENT), or KILO_KIND_UNKNOWN. */
static inline uint8_t kilo_host_msg_kind(uint8_t type)
{
    switch (type) {
    case KILO_HOST_MSG_STATUS_REQ:
    case KILO_HOST_MSG_CONTROL:
    case KILO_HOST_MSG_POSTURE:
    case KILO_HOST_MSG_PARAM_GET:
    case KILO_HOST_MSG_PARAM_SET:
    case KILO_HOST_MSG_REBOOT:
    case KILO_HOST_MSG_TELEM_SUB:
    case KILO_HOST_MSG_LOG_SUB:
    case KILO_HOST_MSG_BRIDGE_OPEN:
    case KILO_HOST_MSG_BRIDGE_CLOSE:
    case KILO_HOST_MSG_FLASH_BEGIN:
    case KILO_HOST_MSG_FLASH_COMMIT:
    case KILO_HOST_MSG_UPDATE_BEGIN:
    case KILO_HOST_MSG_UPDATE_COMMIT:
    case KILO_HOST_MSG_WALK_LIST:
    case KILO_HOST_MSG_WALK_FETCH:
    case KILO_HOST_MSG_REC_STATUS_REQ:
    case KILO_HOST_MSG_REC_FETCH:
    case KILO_HOST_MSG_METRICS_REQ:
    case KILO_HOST_MSG_REC_BENCH:
    case KILO_HOST_MSG_REC_SAVE:
    case KILO_HOST_MSG_REC_DELETE:
    case KILO_HOST_MSG_GUARD:
    case KILO_HOST_MSG_CAL:
    case KILO_HOST_MSG_SOUND:
    case KILO_HOST_MSG_SOUND_LIST:
        return KILO_KIND_COMMAND;
    case KILO_HOST_MSG_KEEPALIVE:
    case KILO_HOST_MSG_BRIDGE_TX:
    case KILO_HOST_MSG_FLASH_DATA:
    case KILO_HOST_MSG_UPDATE_DATA:
    case KILO_HOST_MSG_TELEM:
    case KILO_HOST_MSG_LOG_LINE:
    case KILO_HOST_MSG_BRIDGE_RX:
    case KILO_HOST_MSG_WALK_DATA:
    case KILO_HOST_MSG_BENCH_RESULT:
    case KILO_HOST_MSG_FLASH_STATUS:
    case KILO_HOST_MSG_UPDATE_STATUS:
        return KILO_KIND_STREAM;
    case KILO_HOST_MSG_RESULT:
    case KILO_HOST_MSG_STATUS:
    case KILO_HOST_MSG_WALK_INFO:
    case KILO_HOST_MSG_REC_STATUS:
    case KILO_HOST_MSG_METRICS:
    case KILO_HOST_MSG_GUARD_STATUS:
    case KILO_HOST_MSG_CAL_STATUS:
    case KILO_HOST_MSG_SOUND_STATUS:
    case KILO_HOST_MSG_SOUND_INFO:
        return KILO_KIND_EVENT;
    default:
        return KILO_KIND_UNKNOWN;
    }
}

/* The reply message of a host query, 0 for any other type (answered by RESULT or not at all). */
static inline uint8_t kilo_host_query_reply(uint8_t type)
{
    switch (type) {
    case KILO_HOST_MSG_STATUS_REQ:
        return KILO_HOST_MSG_STATUS;
    case KILO_HOST_MSG_WALK_LIST:
        return KILO_HOST_MSG_WALK_INFO;
    case KILO_HOST_MSG_REC_STATUS_REQ:
        return KILO_HOST_MSG_REC_STATUS;
    case KILO_HOST_MSG_METRICS_REQ:
        return KILO_HOST_MSG_METRICS;
    case KILO_HOST_MSG_GUARD:
        return KILO_HOST_MSG_GUARD_STATUS;
    case KILO_HOST_MSG_CAL:
        return KILO_HOST_MSG_CAL_STATUS;
    case KILO_HOST_MSG_SOUND:
        return KILO_HOST_MSG_SOUND_STATUS;
    case KILO_HOST_MSG_SOUND_LIST:
        return KILO_HOST_MSG_SOUND_INFO;
    default:
        return 0u;
    }
}

